/* WaitMapper.selectWaitList */ ( SELECT B_SEQ, B_MSG_KEY, LOGIN_ID, USER_ID, TITLE, MSG, REPLACE( REPLACE( REPLACE( CONVERT(VARCHAR(19), IN_TIME, 120), '-', ''), ':', ''), ' ', '') AS IN_TIME, REPLACE( REPLACE( REPLACE( CONVERT(VARCHAR(19), REQ_TIME, 120), '-', ''), ':', ''), ' ', '') AS REQ_TIME, CNT, STATUS, SVC_TYPE FROM T_BROADCAST_MSG WHERE REPLACE(REPLACE(REPLACE(CONVERT(VARCHAR(19), REQ_TIME, 120), '-', ''), ':', ''), ' ', '') >= #{startTime} AND REPLACE(REPLACE(REPLACE(CONVERT(VARCHAR(19), REQ_TIME, 120), '-', ''), ':', ''), ' ', '') <= #{endTime}
AND TITLE LIKE CONCAT('%', #{waitTitle}, '%')
)
ORDER BY
${s.selector}
DESC ASC
ORDER BY B_SEQ DESC
OFFSET #{skip} ROWS FETCH NEXT #{take} ROWS ONLY

/*
	WaitMapper.selectWaitCount
*/
SELECT COUNT(*) FROM (			
	SELECT 1 AS CNT
	FROM T_BROADCAST_MSG
	WHERE REPLACE(REPLACE(REPLACE(CONVERT(VARCHAR(19), REQ_TIME, 120), '-', ''), ':', ''), ' ', '') >= #{startTime}
		AND REPLACE(REPLACE(REPLACE(CONVERT(VARCHAR(19), REQ_TIME, 120), '-', ''), ':', ''), ' ', '') <= #{endTime}

		AND TITLE LIKE CONCAT('%', #{waitTitle}, '%')

) TOTAL
